def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if not col or (r,c) in seen: continue
            st=[(r,c)]; seen.add((r,c)); cells=[]
            while st:
                x,y=st.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=x+dx,y+dy
                    if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==col and q not in seen:
                        seen.add(q); st.append(q)
            comps.append((col,cells))
    # Identify the unique singleton-colored component class via exact shape
    # congruence, allowing rotations/reflections; recolor the lone member to
    # the color of the recurring matching class.
    def shape_variants(cells):
        pts=cells; variants=set()
        for flip in (1,-1):
            for rot in range(4):
                q=[]
                for x,y in pts:
                    a,b=x,flip*y
                    for _ in range(rot): a,b=b,-a
                    q.append((a,b))
                mx=min(a for a,b in q); my=min(b for a,b in q)
                variants.add(frozenset((a-mx,b-my) for a,b in q))
        return variants
    records=[]; color_counts={}
    for col,cells in comps:
        color_counts[col]=color_counts.get(col,0)+1
        records.append((col,cells,shape_variants(cells)))
    for col,cells,var in records:
        if col!=1: continue
        candidates=[]
        for other,ocells,ovar in records:
            if other!=1 and var & ovar: candidates.append(other)
        if candidates:
            # Pick the matching component whose color has multiple instances;
            # if tied, choose the first spatially.
            target=next((x for x in candidates if color_counts.get(x,0)>1),candidates[0])
            for r,c in cells: out[r][c]=target
    return out
