        for c in range(w):
            col=grid[r][c]
            if not col or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=x+dx,y+dy
                    if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==col and q not in seen:
                        seen.add(q); stack.append(q)
            mr=min(x for x,y in cells); mc=min(y for x,y in cells)
            shape=frozenset((x-mr,y-mc) for x,y in cells)
            comps.append((col,cells,shape))
    refs={}
    for col,cells,shape in comps:
        if col!=1: refs.setdefault(shape,col)
    for col,cells,shape in comps:
        if col==1 and shape in refs:
            for r,c in cells: out[r][c]=refs[shape]
    return out
